/* Auth gate — only meaningful for the manual webhook input
   (schedule-triggered items carry no headers). */
const input = $input.first().json;
if (input.headers) {
  const provided = String(input.headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (provided !== $env.CHAT_API_KEY) {
    return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key. Provide it via the Authorization: Bearer header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
  }
}
return [{ json: { ok: true } }];

/* Enforce data-table retention via the n8n public API.
   Rows older than RETENTION_DAYS_* are deleted; a dry-run first counts
   what would go, then the real delete only runs when count > 0. */
const base = 'http://localhost:5678/api/v1';
const headers = { 'X-N8N-API-KEY': $env.N8N_API_KEY };
const api = (method, path, qs) => this.helpers.httpRequest({ method, url: base + path, headers, qs });

const tables = await api('GET', '/data-tables', { limit: 100 });
const byName = {};
for (const t of tables.data || []) byName[t.name] = t.id;

const jobs = [
  { table: 'chat_messages', days: Number($env.RETENTION_DAYS_MESSAGES || 30) },
  { table: 'chat_executions', days: Number($env.RETENTION_DAYS_EXECUTIONS || 90) },
  // idempotency records are only useful for a few minutes; keep a week so
  // a replay can still be explained after the fact.
  { table: 'idempotency_records', days: Number($env.RETENTION_DAYS_IDEMPOTENCY || 7) },
];

const results = [];
for (const job of jobs) {
  const tableId = byName[job.table];
  if (!tableId) {
    results.push({ table: job.table, error: 'table not found' });
    continue;
  }
  const filter = JSON.stringify({
    type: 'and',
    filters: [{ columnName: 'createdAt', condition: 'lt', value: new Date(Date.now() - job.days * 86400000).toISOString() }],
  });
  try {
    const preview = await api('DELETE', `/data-tables/${tableId}/rows/delete`, { filter, dryRun: 'true', returnData: 'true' });
    const count = Array.isArray(preview) ? preview.length : 0;
    if (count > 0) {
      await api('DELETE', `/data-tables/${tableId}/rows/delete`, { filter });
    }
    results.push({ table: job.table, cutoff_days: job.days, deleted: count });
  } catch (e) {
    results.push({ table: job.table, error: String(e && e.message ? e.message : e).slice(0, 200) });
  }
}
return [{ json: { retention: results, ran_at: new Date().toISOString() } }];
